{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "In an in vivo PK study in mice, compound 27 was detected in brain tissue after systemic administration, with brain concentrations about 10-20% of blood, indicating partial BBB passage and brain accumulation.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Benzamide 19 with a 1-benzyl-4-piperidinyl amide substituent showed significant and lasting high brain uptake in C57 Black mice.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "In rats given 14C-DY-9760e, brain radioactivity was only 3-4% of plasma and brain was among the lowest tissues, indicating poor BBB penetration.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The highest-scoring transferred evidence shows systemic brain exposure, and multiple direct brain-uptake/PET records support meaningful CNS access; conflicting low brain/plasma records lower confidence but do not overturn the positive weighted evidence.",
  "evidence_gaps": [
    "Direct in-vivo outcomes conflict across transferred molecules, with some records showing high brain uptake and others showing low brain/plasma ratios or no brain radioactivity.",
    "Some positive records are family-level PET observations rather than direct measurements on the exact analogue."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

